// The darkness slider runs 0..1 and only moves the black threshold: 0 leaves
// tones as they are, and higher values send more of the darkest tones and
// grays to pure black (up to MAX_BLACK_THRESHOLD of the brightness range).
const DEFAULT_DARKNESS = 0.5;

const SETTINGS_DIR = GLib.build_filenamev([GLib.get_user_config_dir(), 'darkshift']);
const SETTINGS_FILE = GLib.build_filenamev([SETTINGS_DIR, 'settings.json']);

// colorShift runs 0..1 from green (0) to red (1): it moves that share of the
// green channel onto red. maxValue runs 0..1 and scales the brightest value
// any channel can reach, from 33% (0) to full (1).
const DEFAULT_SETTINGS = {darkness: DEFAULT_DARKNESS, colorShift: 0, maxValue: 1};

function loadSettings() {
    const settings = {...DEFAULT_SETTINGS};
    try {
        const [, bytes] = GLib.file_get_contents(SETTINGS_FILE);
        const saved = JSON.parse(new TextDecoder().decode(bytes));
        for (const key of Object.keys(settings)) {
            if (typeof saved[key] === 'number' && saved[key] >= 0 && saved[key] <= 1)
                settings[key] = saved[key];
        }
    } catch (e) {
        // No saved values yet (or unreadable): use the defaults.
    }
    return settings;
}

function saveSettings(settings) {
    try {
        GLib.mkdir_with_parents(SETTINGS_DIR, 0o755);
        GLib.file_set_contents(SETTINGS_FILE, JSON.stringify(settings));
    } catch (e) {
        console.error(`Darkshift: failed to save settings: ${e}`);
    }
}
