class DarkshiftToggle extends QuickMenuToggle {
    constructor(settings) {
        super({
            title: _('Darkshift'),
            iconName: 'preferences-desktop-display-symbolic',
            toggleMode: true,
        });

        this.menu.setHeader('preferences-desktop-display-symbolic', _('Darkshift'));

        this.extremeItem = new PopupMenu.PopupMenuItem(_('Monotone'));
        this.extremeItem.setOrnament(PopupMenu.Ornament.NONE);
        // Overriding activate() (rather than connecting to the signal) keeps
        // the menu open, since the menu closes itself on 'activate'.
        this.extremeItem.activate = () => {
            this.extreme = !this.extreme;
        };
        this.menu.addMenuItem(this.extremeItem);

        this.menu.addMenuItem(new PopupMenu.PopupSeparatorMenuItem());

        this.settings = {...settings};
        this._sliders = {};
        this._addSlider('darkness', _('Darkness'));
        this._colorSliderItem = this._addSlider('colorShift', _('Green \u2192 Red'));

        // Monotone mode has no in-between: just pick green or red.
        this._colorChoiceItem = new PopupMenu.PopupBaseMenuItem({activate: false});
        this._colorChoices = [[_('Green'), 0], [_('Red'), 1]].map(([label, value]) => {
            const button = new St.Button({
                label,
                style_class: 'button',
                toggle_mode: true,
                can_focus: true,
                x_expand: true,
            });
            button.connect('clicked', () => {
                this.settings.colorShift = value;
                this._updateColorChoices();
                this.emit('settings-changed');
            });
            this._colorChoiceItem.add_child(button);
            return {button, value};
        });
        this.menu.addMenuItem(this._colorChoiceItem);

        this._addSlider('maxValue', _('Max value'));

        this.menu.addMenuItem(new PopupMenu.PopupSeparatorMenuItem());

        const resetItem = new PopupMenu.PopupMenuItem(_('Reset to defaults'));
        resetItem.activate = () => this._reset();
        this.menu.addMenuItem(resetItem);

        this.extreme = this.settings.monotone;
    }

    _addSlider(key, label) {
        const sliderItem = new PopupMenu.PopupBaseMenuItem({activate: false});
        const slider = new Slider(this.settings[key]);
        this._sliders[key] = slider;
        slider.x_expand = true;
        slider.connect('notify::value', () => {
            this.settings[key] = slider.value;
            this.emit('settings-changed');
        });
        sliderItem.add_child(new St.Label({
            text: label,
            y_align: Clutter.ActorAlign.CENTER,
        }));
        sliderItem.add_child(slider);
        this.menu.addMenuItem(sliderItem);
        return sliderItem;
    }

    _updateColorChoices() {
        const red = this.settings.colorShift >= 0.5 ? 1 : 0;
        this._colorSliderItem.visible = !this._extreme;
        this._colorChoiceItem.visible = this._extreme;
        this._colorChoices.forEach(({button, value}) => {
            button.checked = value === red;
        });
    }

    _reset() {
        Object.entries(this._sliders).forEach(([key, slider]) => {
            slider.value = DEFAULT_SETTINGS[key];
        });
        this.extreme = DEFAULT_SETTINGS.monotone;
        this._updateColorChoices();
        this.emit('settings-changed');
    }

    get extreme() {
        return this._extreme;
    }

    set extreme(value) {
        this._extreme = value;
        this.settings.monotone = value;
        this.extremeItem.setOrnament(value ? PopupMenu.Ornament.CHECK : PopupMenu.Ornament.NONE);
        this._updateColorChoices();
        this.emit('extreme-changed');
    }
});

